            order.append(ch)
    for ch in 'ABCDEFGHIKLMNOPQRSTUVWXYZ':
        if ch not in order:
            order.append(ch)
    sq = ''.join(order)
    pos = {}
    for i, ch in enumerate(sq):
        pos[ch] = (i // 5, i % 5)
    s = []
    for ch in FAED.upper():
        r, c = pos[ch]
        s.append(r)
        s.append(c)
    n = len(FAED)
    dec = ''.join(sq[s[i] * 5 + s[n + i]] for i in range(n))
    tail = dec[7:]
    N = int('FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141', 16)
    def hmac512(key, msg):
        blk = 128
        if len(key) > blk:
            key = hashlib.sha512(key).digest()
        key = key + b'\x00' * (blk - len(key))
        ik = bytes(b ^ 0x36 for b in key)
        ok = bytes(b ^ 0x5c for b in key)
        return hashlib.sha512(ok + hashlib.sha512(ik + msg).digest()).digest()
    seeds = [tail, tail.lower(), tail[0::2], tail[1::2], tail[:64], tail[:32], dec, dec.lower(), DBBI, FAED,
             'BTCSEED' + tail, tail[::-1]]
    out = []
    for sd in seeds:
        if not sd:
            continue
        m = hmac512(b'Bitcoin seed', sd.encode())
        out.append(m[:32].hex())
        out.append(m[32:].hex())
        out.append(hashlib.sha256(sd.encode()).hexdigest())
    for sd in seeds[:4]:
        try:
            sd2 = hashlib.pbkdf2_hmac('sha512', sd.encode(), b'mnemonic', 2048)
            m = hmac512(b'Bitcoin seed', sd2)
            out.append(m[:32].hex())
        except Exception:
            pass
    # tail letters as one big base-25 number, reduced into the curve order
    v = 0
    for ch in tail:
        v = v * 25 + sq.index(ch)
    for val in (v % N, (v >> 256) % N, v & ((1 << 256) - 1)):
        if val:
            out.append('%064x' % val)
    seen = []
    for x in out:
        if x not in seen:
            seen.append(x)
    return seen

